SelectionModes.Mode:
SELECT
			MA_SaleOrd.InternalOrdNo {COL MA_SaleOrd.InternalOrdNo TITLE "InternalOrdNo"},
			MA_SaleOrd.OrderDate  {COL MA_SaleOrd.OrderDate TITLE "OrderDate"},
			MA_SaleOrd.ExternalOrdNo  {COL MA_SaleOrd.ExternalOrdNo TITLE "ExternalOrdNo"},
			MA_SaleOrd.Customer  {COL MA_SaleOrd.Customer TITLE "Customer"}
		FROM MA_SaleOrd
		WHERE 
			MA_SaleOrd.ExternalOrdNo LIKE { IN filter_value } and
			MA_SaleOrd.OrderDate >= { IN orderDate }  
			{ WHEN NOT IsEmpty(Customer)  EXPAND { AND MA_SaleOrd.Customer = { IN Customer } } }

SELECT
			MA_SaleOrd.InternalOrdNo {COL MA_SaleOrd.InternalOrdNo TITLE "InternalOrdNo"},
			MA_SaleOrd.OrderDate  {COL MA_SaleOrd.OrderDate TITLE "OrderDate"},
			MA_SaleOrd.ExternalOrdNo  {COL MA_SaleOrd.ExternalOrdNo TITLE "ExternalOrdNo"},
			MA_SaleOrd.Customer  {COL MA_SaleOrd.Customer TITLE "Customer"},
			MA_SaleOrd.Payment  {COL MA_SaleOrd.Payment TITLE "Payment"}
		FROM MA_SaleOrd
		WHERE 
			 MA_SaleOrd.CustSuppType = { 49 : 0 }
			{ WHEN NOT IsEmpty(Customer)  EXPAND { AND MA_SaleOrd.Customer = { IN Customer } } }
			{ WHEN NOT IsEmpty(Payment)  EXPAND { AND MA_SaleOrd.Payment LIKE { IN Payment } } }
